selector_to_html = {"a[href=\"#inspecting-element-attributes\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Inspecting Element Attributes<a class=\"headerlink\" href=\"#inspecting-element-attributes\" title=\"Link to this heading\">#</a></h1><p>When the snapshot doesn\u2019t show an element\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">id</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">class</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">data-*</span></code> attributes, or other DOM properties, use <code class=\"docutils literal notranslate\"><span class=\"pre\">eval</span></code> to inspect them.</p>", "a[href=\"#examples\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
